css.jcStani:
/* Updated 18 August 2020 */
/* some things fixed by me rinkishimo - previously by mark*/

:root {
	--accent-color: #ff3030;
	--health-color: #1fff2a;
	--ammo-color: #69fcff;
	--premium-color: #fbc02d;
	--verified-color: #40c4ff;
	--menu-bg-color: transparent;
	--text-transform: lowercase;
}

@font-face {
	font-family: gamefont;
	src: url(https://fonts.gstatic.com/s/montserrat/v14/JTURjIg1_i6t8kCHKm45_c5H3gnD_g.woff2);
}

@font-face {
	font-family: hpammo;
	src: url(https://fonts.gstatic.com/s/montserrat/v14/JTURjIg1_i6t8kCHKm45_c5H3gnD_g.woff2);
}

* {
	color: var(--accent-color);
}

/*XDDDDD*/

#bottomLeftChallIcon, 
#bottomLeftPlayerLeft, 
#bottomLeftPlayerMid, 
.weapItemInner, 
#timerIcon.topLeftOld, 
#matchInfo.topLeftOld, 
.material-icons-outlined, 
#matchInfoHolder, 
#leftTabsHolder, 
.streams-overlay.closed.svelte-9szequ,
#walletContainer, 
#reloadMsg {
	display: none !important;
}


.greyInner, #timerInner.topLeftOld, .statIcon, #leaderboardHolder, #leaderContainer, #menuItemContainer, #chatInputHolder .greyInlineInner, #chatInputHolder .greyInlineInnerMid{
	background-color: transparent !important;
}

.buttonO, 
.buttonR, 
.buttonP, 
.buttonPI, 
.buttonG, 
.buttonB,
#menuBtnRanked   {
    border: 0 !important;
	transform: none !important;
}

.verticalSeparatorInline{
	border-left:transparent !important;
}
#termsInfo{
	padding: 1px 1px 1px 10px;
}

.button:hover, #menuBtnRanked:hover{
	border: 0 !important;
}
/*upodated*/
[style*="color:#eb5656"] {
	color: var(--accent-color) !important;
}

[style*="color:rgba(0,0,0,0.3)"] {
	color: rgba(255, 255, 255, 1) !important;
}

[style*="color:#9eeb56"] {
	color: rgba(255, 255, 255, 1) !important;
}

[style*="font-size:20px;color:#fff;display:inline-block;"] {
	color: var(--accent-color) !important;
}

[style*="margin-top:10px;font-size:20px;color:rgba(255,255,255,1)"] {
	display: none !important;
}

a {
	color: var(--accent-color);
}

a:active {
	color: var(--accent-color);
}

a:visited {
	color: var(--accent-color);
}

a:hover {
	color: #fff;
	text-decoration: none;
}

.material-icons {
	font-family: 'Material Icons';
	font-size: 24px;
	font-style: normal;
	font-weight: 400;
}

.material-icons[style*="color:#FBC02D"] {
	color: var(--verified-color) !important;
}

.material-icons[style*="color:#40C4FF"] {
	color: var(--verified-color) !important;
}

#aHolder {
	display: none !important;
}

.endAHolder {
	display: none !important;
}

#mainLogo {
	display: none !important;
}

#streamContainer {
	display: none !important;
}

#merchImg {
	display: none;
}

#uiBase.onMenu #spectButton {
	left: 20px;
	transform: none;
	text-transform: var(--text-transform);
}

#uiBase.onMenu #claimHolder {
	left: 20px;
	transform: none;
}

#claimImg {
	height: 70px;
}

#claimTimer {
	text-transform: var(--text-transform);
}

#braveWarning {
	display: none !important;
}

.button {
	background-color: transparent !important;
	color: var(--accent-color) !important;
	text-shadow: none !important;
	box-shadow: none !important;
	text-transform: var(--text-transform);
}

.button:hover {
